// Version A: explicit result object
async function fetchUserA(id: string): Promise<{ user?: User; notFound: boolean }> {
  const u = await db.find(id);
  return { user: u ?? undefined, notFound: u == null };
}

// Version B: nullable return plus selective throws
async function fetchUserB(id: string): Promise<User | null> {
  try {
    return await db.find(id);
  } catch (e) {
    if (e.code === 'TIMEOUT') throw e;
    return null;
  }
}
